function topicLedger(){const q=scope(),ys=scopeYears(),families=[...new Set(q.map(x=>x.subject+'\u0000'+x.topic_family))],a=families.map(key=>{let [subject,topic]=key.split('\u0000'),rows=q.filter(x=>x.subject===subject&&x.topic_family===topic),annual=ys.map(y=>sum(rows.filter(x=>x.year===y).map(x=>x.marks))),seen=ys.filter((y,i)=>annual[i]>0),gaps=seen.slice(1).map((y,i)=>y-seen[i]-1);return {subject,topic,n:rows.length,marks:sum(annual),annual,seen,gap:gaps.length?mean(gaps):null}}).sort((a,b)=>b.marks-a.marks);return '<div style="height:18px"></div>'+panel('03','Topic-family recurrence ledger','Versioned consolidation of reviewed fine-grained tags · selected years only',`<div class="table-scroll" style="max-height:540px"><table class="data-table"><thead><tr><th>Topic family / subject</th><th>Questions</th><th>Marks</th><th>Present / papers</th><th>Mean absent-year gap</th><th>Last observed</th><th>Weight history</th></tr></thead><tbody>${a.map(x=>`<tr data-topic-family="${E(x.topic)}" data-subject="${E(x.subject)}"><td>${E(x.topic)}<small>${E(x.subject)}</small></td><td class="numeric">${x.n}</td><td class="numeric">${x.marks}</td><td class="numeric">${x.seen.length} / ${ys.length}</td><td class="numeric">${x.gap===null?'—':F(x.gap,2)}</td><td class="numeric">${x.seen.at(-1)||'—'}</td><td>${spark(x.annual)}</td></tr>`).join('')}</tbody></table></div>`,'','Observed recurrence is not future appearance probability. Fine-grained reviewed labels remain in the audit. Click to inspect matching questions.')}
document.addEventListener('click',e=>{let r=e.target.closest('[data-topic-family]');if(r){query=r.dataset.topicFamily;verdict='all';page=0;location.hash='questions';if(view==='questions')render()}});
